            && path != "eab"
            && !path.starts_with("eab/")
            && !path.starts_with("acme/")
            && !path.contains("/acme/")
            && !matches!(
                path,
                "root/generate/kms" | "intermediate/generate/kms" | "keys/generate/kms"
            )
    }
